// Rates, the Wilson interval, tiers, quantiles and the time-to-event histogram (SPEC § 9).

export const Z = 1.959963984540054;
export const ANECDOTAL_BELOW = 10;
export const THIN_BELOW = 30;
export const HALF_MIN = 10;
export const TIMING_MIN = 10;
export const WIDE_INTERVAL = 0.3;

export type Tier = 'none' | 'anecdotal' | 'thin' | 'ok';

export interface GroupStats {
  n: number;
  k: number;
  rate: number | null;
  lo: number | null;
  hi: number | null;
  tier: Tier;
}

export function tierOf(n: number): Tier {
  return n === 0 ? 'none' : n < ANECDOTAL_BELOW ? 'anecdotal' : n < THIN_BELOW ? 'thin' : 'ok';
}

/** The 95% Wilson score interval, computed in exactly the order SPEC § 9.2 writes it. */
export function wilson(k: number, n: number): { rate: number | null; lo: number | null; hi: number | null } {
  if (n === 0) return { rate: null, lo: null, hi: null };
  const z = Z;
  const p = k / n;
  const denom = 1 + z * z / n;
  const center = (p + z * z / (2 * n)) / denom;
  const half = (z / denom) * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n));
  const lo = k === 0 ? 0 : Math.max(0, center - half);
  const hi = k === n ? 1 : Math.min(1, center + half);
  return { rate: p, lo, hi };
}

export function groupStats(k: number, n: number): GroupStats {
  const w = wilson(k, n);
  return { n, k, rate: w.rate, lo: w.lo, hi: w.hi, tier: tierOf(n) };
}

/** Type 7 quantile of ascending values. */
export function quantile7(sorted: number[], p: number): number {
  const m = sorted.length;
  const h = (m - 1) * p;
  const j = Math.floor(h);
  if (j >= m - 1) return sorted[m - 1];
  return sorted[j] + (h - j) * (sorted[j + 1] - sorted[j]);
}

export const BIN_LADDER = [1, 2, 5, 10, 15, 30, 60, 120, 240];

/** The smallest ladder width w with ceil(L / w) <= 24. */
export function binWidth(L: number): number {
  for (const w of BIN_LADDER) if (Math.ceil(L / w) <= 24) return w;
  return BIN_LADDER[BIN_LADDER.length - 1];
}

export interface TimeToEvent {
  start: string;
  count: number;
  min: number | null;
  max: number | null;
  mean: number | null;
  p10: number | null;
  p25: number | null;
  p50: number | null;
  p75: number | null;
  p90: number | null;
  binWidth: number | null;
  bins: { lo: number; hi: number; count: number; cumulative: number }[];
}

/**
 * The time-to-event distribution over the setup group's hits. `minutes` are in date order;
 * `n` is the setup group's size; `longest` the longest observation window over its measured sessions.
 */
export function timeToEvent(start: string, minutes: number[], n: number, longest: number): TimeToEvent {
  const count = minutes.length;
  if (count === 0)
    return { start, count: 0, min: null, max: null, mean: null, p10: null, p25: null, p50: null, p75: null, p90: null, binWidth: null, bins: [] };
  let sum = 0;
  for (const x of minutes) sum += x;
  const sorted = [...minutes].sort((a, b) => a - b);
  const w = binWidth(longest);
  const B = Math.ceil(longest / w);
  const counts = new Array<number>(B).fill(0);
  for (const x of minutes) {
    const i = Math.ceil(x / w) - 1;
    if (i >= 0 && i < B) counts[i]++;
  }
  let cum = 0;
  const bins = counts.map((c, i) => {
    cum += c;
    return { lo: i * w, hi: (i + 1) * w, count: c, cumulative: cum / n };
  });
  return {
    start,
    count,
    min: sorted[0],
    max: sorted[count - 1],
    mean: sum / count,
    p10: quantile7(sorted, 0.1),
    p25: quantile7(sorted, 0.25),
    p50: quantile7(sorted, 0.5),
    p75: quantile7(sorted, 0.75),
    p90: quantile7(sorted, 0.9),
    binWidth: w,
    bins,
  };
}
